//! The party's data, generated by `tools/party_sheet.js` from `sheets/port/party-*.json` into
//! `build/gen/rust/party_data.rs` (each row cites its asset / address in the sheet), and the
//! lookups the rest of the crate uses.

#[allow(unused_imports)]
use crate::anim::{AnimSetTable, ClipDef, ClipNotify, ClipNotifyData, RootKey, SocketKey};
use crate::ids::Chara;

/// One row of `n_ex00x_AttackDataTable` (`TresAttackDataTable`).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct AttackRow {
    pub chara: u8,
    pub name: &'static str,
    pub power: f32,
    /// `ETresDamageKind` tail ("TRES_DMG_KIND_SMALL").
    pub damage_kind: &'static str,
    /// `ETresDamageAttribute` tail ("TRES_DMG_ATTR_FIRE").
    pub attribute: &'static str,
    pub power_scale: f32,
    pub parabola_angle: f32,
    pub move_length: f32,
    pub brake: f32,
    pub knockback: &'static str,
    pub effect_time: f32,
    pub bad_status: &'static str,
    pub bad_rate: f32,
    pub bad_time: f32,
    pub team_check: &'static str,
    pub reaction_power: i32,
    pub magic: bool,
    pub reflect_level: i32,
}

include!(concat!(env!("KH_PARTY_GEN_DIR"), "/party_data.rs"));

// Stream A's tables (tools/gen_party.js, every row with A's decoded notifies; root / socket tracks as A packs them).
#[cfg(kh_party_anim_a)]
mod a_ex001 {
    use super::*;
    include!(concat!(env!("KH_PARTY_GEN_DIR"), "/party_clips_n_ex001.rs"));
}
#[cfg(kh_party_anim_b)]
mod a_ex002 {
    use super::*;
    include!(concat!(env!("KH_PARTY_GEN_DIR"), "/party_clips_n_ex002.rs"));
}

/// A scalar of `party-params` by id. Panics on an unknown id: every id the code uses is a row
/// of the sheet, and the unit test `every_param_used_exists` walks them.
pub fn param(id: &str) -> f32 {
    match PARTY_PARAMS.iter().find(|(k, _)| *k == id) {
        Some(&(_, v)) => v,
        None => panic!("party-params has no row {id}"),
    }
}

/// `param` for a per-character row: `"<n_ex00x>.<rest>"`.
pub fn cparam(chara: Chara, rest: &str) -> f32 {
    param(&format!("{}.{}", chara.model(), rest))
}

/// An action definition's number: `act.<n_ex00x>.<asset>.<field>`.
pub fn aparam(chara: Chara, asset: &str, field: &str) -> f32 {
    param(&format!("act.{}.{}.{}", chara.model(), asset, field))
}

/// The level row (1..=99) of a character.
pub fn level_row(chara: Chara, level: u32) -> (i32, i32, i32, i32, i32) {
    let uid = chara.uid();
    let lv = level.clamp(1, 99);
    let r = PARTY_LEVELS.iter().find(|r| r.0 == uid && r.1 == lv).expect("party-levels row");
    (r.2, r.3, r.4, r.5, r.6)
}

/// The level a shared EXP total gives this character: the highest row whose EXP is reached
/// (`CheckLevelUp` 0x140EBE400 against the character's own table; stats spec 5.2).
pub fn level_for_exp(chara: Chara, total_exp: i32) -> u32 {
    let uid = chara.uid();
    PARTY_LEVELS.iter().filter(|r| r.0 == uid && r.2 <= total_exp).map(|r| r.1).max().unwrap_or(1)
}

pub fn attack_row(chara: Chara, name: &str) -> Option<&'static AttackRow> {
    PARTY_ATTACKS.iter().find(|r| r.chara == chara.uid() && r.name == name)
}

/// A weapon row by item row ("I03021") or key ("WEP_DONALD_00"):
/// (row, key, uid, strength, magic, defense, abilities, model).
pub fn weapon(id: &str) -> Option<&'static (&'static str, &'static str, u8, i32, i32, i32, &'static [&'static str], &'static str)> {
    PARTY_WEAPONS.iter().find(|w| w.0 == id || w.1 == id)
}

/// (AP, MP) of an ability key; MP -1 = all MP.
pub fn ability_cost(key: &str) -> Option<(i32, i32)> {
    PARTY_ABILITIES.iter().find(|a| a.0 == key).map(|a| (a.1, a.2))
}

/// Stream A's generated tables when they exist, else the minimal tables of `party_sheet.js`.
pub fn anim_set(chara: Chara) -> AnimSetTable {
    match chara {
        #[cfg(kh_party_anim_a)]
        Chara::Donald => *a_ex001::N_EX001_ANIMS, // (PACKGEN) a run-time table in the release build (kh-gendata)
        #[cfg(not(kh_party_anim_a))]
        Chara::Donald => AnimSetTable { chara, clips: N_EX001_MIN_CLIPS },
        #[cfg(kh_party_anim_b)]
        Chara::Goofy => *a_ex002::N_EX002_ANIMS, // (PACKGEN) a run-time table in the release build (kh-gendata)
        #[cfg(not(kh_party_anim_b))]
        Chara::Goofy => AnimSetTable { chara, clips: N_EX002_MIN_CLIPS },
    }
}

/// A clip that always exists (a state asking for a row the set lacks gets this, and the
/// lookup is reported by the unit tests).
pub static EMPTY_CLIP: ClipDef = ClipDef::bare("", 0.5, false);

/// The clip of a row, or `EMPTY_CLIP`.
pub fn clip(chara: Chara, name: &str) -> &'static ClipDef {
    anim_set(chara).get(name).unwrap_or(&EMPTY_CLIP)
}

#[allow(dead_code)]
fn _types_used(_: ClipNotify, _: ClipNotifyData) {}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn level_tables_match_the_plan() {
        // plan 2.3 [A]
        assert_eq!(level_row(Chara::Donald, 1), (0, 11, 16, 11, 14));
        assert_eq!(level_row(Chara::Donald, 20), (28242, 21, 26, 21, 18));
        assert_eq!(level_row(Chara::Donald, 99), (1512931, 63, 67, 63, 34));
        assert_eq!(level_row(Chara::Goofy, 99), (1520285, 65, 65, 63, 34));
        // Sora's level-99 EXP reaches both tables' row 99; his level-20 EXP (29,440) gives 20 to both.
        assert_eq!(level_for_exp(Chara::Donald, 1_527_640), 99);
        assert_eq!(level_for_exp(Chara::Goofy, 1_527_640), 99);
        assert_eq!(level_for_exp(Chara::Donald, 29_440), 20);
        assert_eq!(level_for_exp(Chara::Goofy, 29_440), 20);
        assert_eq!(level_for_exp(Chara::Goofy, 28_840), 19);
    }

    #[test]
    fn rows_from_the_assets() {
        assert_eq!(cparam(Chara::Donald, "base.max_hp"), 140.0);
        assert_eq!(cparam(Chara::Goofy, "base.max_hp"), 160.0);
        assert_eq!(cparam(Chara::Donald, "base.damage_max"), 24.0);
        assert_eq!(aparam(Chara::Goofy, "Attack6_Tornado", "fMoveTime"), 3.0);
        assert_eq!(aparam(Chara::Goofy, "Attack7_Turbo", "fMoveSpeed"), 900.0);
        assert_eq!(aparam(Chara::Goofy, "Attack8_Discus", "fStartSpeed"), 2500.0);
        assert_eq!(attack_row(Chara::Donald, "MAG_FIRE").unwrap().power, 1.5);
        assert_eq!(weapon("WEP_DONALD_00").unwrap().3, 3);
        // (DON-PROG) KH3's TresAbilityData row (still the gate's m_UseMP: FriendStatus::don_tree_gate), though no Donald holds it
        assert_eq!(ability_cost("DONALD_CURE"), Some((3, -1)));
        // stream A's tables are in use when generated (they also carry the blend-space rows)
        #[cfg(kh_party_anim_a)]
        assert!(anim_set(Chara::Donald).get("WalkRunN").is_some());
        let beat = clip(Chara::Donald, "M_1301");
        assert!(beat.length > 0.9 && beat.attack_windows().count() == 1, "{beat:?}");
    }
}
